// hello.nova — the basics: typed declarations, inference, pure functions.
//
// Nova is statically typed, but you rarely write the types: `let` infers
// them. Functions are pure by default — no effects unless you say so.

let greeting: String = "Hello"
let target = "Nova"          // inferred: String
let year: Int = 2026
let pi = 3.14159             // inferred: Float
let ready = true             // inferred: Bool

fn greet(name: String) -> String {
  return greeting + ", " + name + "!"
}

fn add(a: Int, b: Int) -> Int {
  return a + b
}

print(greet(target))
print(year)
print(add(20, 22))
print("pi is " + str(pi) + ", ready: " + str(ready))

// counter.nova — Nova's answer to React state.
//
// A component declares its props as parameters and its state with `state`.
// No hooks, no rules-of-hooks footguns: the compiler manages state, and it
// is always correct regardless of declaration order. Event handlers are
// just assignments; firing one updates state and re-renders.

component Counter(title: String) {
  state count: Int = 0

  view {
    <div>
      <h1>{title}</h1>
      <p>{count}</p>
      <button onClick={count = count + 1}>Increment</button>
    </div>
  }
}

let app = render(Counter(title: "Clicks"))
app.fire("onClick")
app.fire("onClick")

// api.nova — Result<T, E> and the `?` operator.
//
// No checked-exception ceremony: fallible functions return Result, and `?`
// propagates the Err automatically. The happy path stays linear.

effect fn fetchUser(id: Int) -> Result[String, String] {
  if id == 1 {
    return Ok("Ada")
  }
  return Err("user " + str(id) + " not found")
}

effect fn greetUser(id: Int) -> Result[String, String] {
  let name = fetchUser(id)?   // Err returns early from greetUser
  return Ok("Hello, " + name + "!")
}

match greetUser(1) {
  Ok(msg) => print(msg),
  Err(e) => print("Error: " + e)
}

match greetUser(7) {
  Ok(msg) => print(msg),
  Err(e) => print("Error: " + e)
}
